def netto(brutto):
    return brutto / 1.19

def mit_rabatt(brutto, prozent):
    return netto(brutto) * (1 - prozent / 100)

print(round(netto(119), 2))
print(round(mit_rabatt(119, 10), 2))

def netto_print(brutto):
    print(brutto / 1.19)

